type lane=Mechanical|Ownership|Metadata
type package=Attribute|Compile_options|Function|Reflection|Library|Type_metadata
type item={id:string;lane:lane;package:package;operation:string;tests:string list}
let mechanical_ids=["method:-[MTLAttribute attributeIndex]";"method:-[MTLAttribute attributeType]";"method:-[MTLAttribute isActive]";"method:-[MTLAttribute isPatchControlPointData]";"method:-[MTLAttribute isPatchData]";"property:MTLAttribute:active";"property:MTLAttribute:attributeIndex";"property:MTLAttribute:attributeType";"property:MTLAttribute:patchControlPointData";"property:MTLAttribute:patchData";"method:-[MTLCompileOptions requiredThreadsPerThreadgroup]";"method:-[MTLCompileOptions setRequiredThreadsPerThreadgroup:]";"property:MTLCompileOptions:requiredThreadsPerThreadgroup"]
let contains s n=let l=String.length n in let rec f i=i+l<=String.length s&&(String.sub s i l=n||f(i+1))in f 0
let classify~kind id=let lane=if List.mem id mechanical_ids then Mechanical else if kind="method"||kind="property"then Ownership else Metadata in let package,operation,tests=if lane=Metadata then Type_metadata,"Metal.Library opaque/reflection/callback types",["public type provenance"]else if contains id "MTLAttribute"||contains id "MTLVertexAttribute"then Attribute,"Metal.Attribute",["typed scalar/name exactness"]else if contains id "MTLCompileOptions"then Compile_options,"Metal.Compile_options",["threadgroup validation";"macro snapshot"]else if contains id "MTLFunctionReflection"then Reflection,"Metal.Function_reflection",["argument ownership";"nullable metadata"]else if contains id "MTLFunction"then Function,"Metal.Function",["device/library identity";"metadata lifetime"]else Library,"Metal.Library",["device identity";"lookup error/nullability";"destroy order"]in{id;lane;package;operation;tests}
let validate items=let count f=List.length(List.filter f items)in if List.length items<>42||count(fun x->x.lane=Mechanical)<>13||count(fun x->x.lane=Ownership)<>21||count(fun x->x.lane=Metadata)<>8||List.map(fun p->count(fun x->x.package=p))[Attribute;Compile_options;Function;Reflection;Library;Type_metadata]<>[12;6;6;4;6;8]then failwith"MTLLibrary42 handoff drift"
